import { Directive, inject, OnInit } from "@angular/core";
import { Store } from "@ngxs/store";
import { fromEvent, tap } from "rxjs";

import { SetWindowWidth } from "../store/action/window-store.action";

@Directive({
    selector: "[appWindowDirective]"
})
export class WindowDirective implements OnInit {
    store = inject(Store);

    ngOnInit() {
        const width = window.innerWidth;
        this.store.dispatch(new SetWindowWidth(width));
        fromEvent(window, "resize").pipe(
            tap(() => this.store.dispatch(new SetWindowWidth(width)))
        ).subscribe();
    }
}

