styleUrlsData.data:
.hamburger {
  width: 32px;
  height: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;

  &__line {
    width: 100%;
    height: 4px;
    background-color: var(--color-surface);
    border-radius: 5px;
    transition: transform 0.25s ease, opacity 0.25s ease;
  }

  &--open {
    .hamburger__line {
      &:nth-child(1) {
        transform: translateY(10px) rotate(45deg);
      }

      &:nth-child(2) {
        opacity: 0;
      }

      &:nth-child(3) {
        transform: translateY(-10px) rotate(-45deg);
      }
    }
  }
}

